export type Priority = "low" | "normal" | "high" | "urgent";

export interface Ticket {
  id: string;
  subject: string;
  priority: Priority;
  requesterEmail: string;
  assigneeId: string | null;
  createdAt: Date;
  updatedAt: Date;
  tags: Set<string>;
  customFields: Map<string, string>;
}

export interface TicketRow {
  id: string;
  subject: string;
  priority: string;
  requester_email: string;
  assignee_id: string | null;
  created_at: Date;
  updated_at: Date;
  tags: string[];
  custom_fields: Record<string, string> | null;
}

const PRIORITIES: Priority[] = ["low", "normal", "high", "urgent"];

export function fromRow(row: TicketRow): Ticket {
  const priority = PRIORITIES.includes(row.priority as Priority) ? (row.priority as Priority) : "normal";
  return {
    id: row.id,
    subject: row.subject,
    priority,
    requesterEmail: row.requester_email,
    assigneeId: row.assignee_id,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    tags: new Set(row.tags),
    customFields: new Map(Object.entries(row.custom_fields ?? {})),
  };
}

import { Ticket } from "./ticket";

export interface TicketDto {
  id: string;
  subject: string;
  priority: string;
  requester: { email: string };
  assigneeId: string | null;
  createdAt: string;
  updatedAt: string;
  tags: string[];
  customFields: Record<string, string>;
}

export function toDto(ticket: Ticket): TicketDto {
  return {
    id: ticket.id,
    subject: ticket.subject,
    priority: ticket.priority,
    requester: { email: ticket.requesterEmail },
    assigneeId: ticket.assigneeId,
    createdAt: ticket.createdAt.toISOString(),
    updatedAt: ticket.updatedAt.toISOString(),
    tags: [...ticket.tags].sort(),
    customFields: ticket.customFields as unknown as Record<string, string>,
  };
}

export function applyPatch(ticket: Ticket, body: unknown): Ticket {
  if (typeof body !== "object" || body === null) throw new Error("invalid body");
  const b = body as Record<string, unknown>;
  const next: Ticket = {
    ...ticket,
    tags: new Set(ticket.tags),
    customFields: new Map(ticket.customFields),
  };
  if (typeof b.subject === "string" && b.subject.trim()) next.subject = b.subject.trim();
  if (b.assigneeId === null || typeof b.assigneeId === "string") next.assigneeId = b.assigneeId;
  if (Array.isArray(b.addTags)) {
    for (const t of b.addTags) if (typeof t === "string") next.tags.add(t.toLowerCase());
  }
  if (b.customFields && typeof b.customFields === "object") {
    for (const [k, v] of Object.entries(b.customFields as Record<string, unknown>)) {
      if (v === null) next.customFields.delete(k);
      else if (typeof v === "string") next.customFields.set(k, v);
    }
  }
  next.updatedAt = new Date();
  return next;
}

import { fromRow, TicketRow } from "./ticket";
import { toDto, applyPatch } from "./ticketDto";

export interface Db {
  findTicket(id: string): Promise<TicketRow | null>;
  updateTicket(row: TicketRow): Promise<void>;
}

export async function getTicket(db: Db, id: string): Promise<{ status: number; body: string }> {
  const row = await db.findTicket(id);
  if (!row) return { status: 404, body: JSON.stringify({ error: "not_found" }) };
  return { status: 200, body: JSON.stringify(toDto(fromRow(row))) };
}

export async function patchTicket(db: Db, id: string, rawBody: string) {
  const row = await db.findTicket(id);
  if (!row) return { status: 404, body: JSON.stringify({ error: "not_found" }) };
  let body: unknown;
  try {
    body = JSON.parse(rawBody);
  } catch {
    return { status: 400, body: JSON.stringify({ error: "malformed_json" }) };
  }
  const updated = applyPatch(fromRow(row), body);
  await db.updateTicket({
    ...row,
    subject: updated.subject,
    assignee_id: updated.assigneeId,
    updated_at: updated.updatedAt,
    tags: [...updated.tags],
    custom_fields: Object.fromEntries(updated.customFields),
  });
  return { status: 200, body: JSON.stringify(toDto(updated)) };
}
